import{_ as a,o as n,c as o,a2 as t}from"./chunks/framework.Di-jvWLj.js";const u=JSON.parse('{"title":"OpenClaw","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/openclaw.md","filePath":"deployment/openclaw.md","lastUpdated":1792690510000}'),s={name:"deployment/openclaw.md"};function l(p,e,r,c,d,i){return n(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="openclaw" tabindex="-1">OpenClaw <a class="header-anchor" href="#openclaw" aria-label="Permalink to &quot;OpenClaw&quot;">​</a></h1><p>OpenClaw is a personal assistant gateway that connects chat channels to agents. chamvi&#39;s integration contract is <strong>&quot;MCP in, hooks out&quot;</strong>.</p><h2 id="mcp-in" tabindex="-1">MCP in <a class="header-anchor" href="#mcp-in" aria-label="Permalink to &quot;MCP in&quot;">​</a></h2><p>Each chamvi app serves an MCP endpoint at <code>/mcp</code> (Streamable HTTP, from <a href="/guide/http#mcp"><code>@chamvi/http</code></a>). OpenClaw lists it among its MCP servers and gets:</p><ul><li>one <code>run_&lt;agent&gt;</code> tool per agent with an <code>http()</code> trigger, which starts a run and returns the run id (or, with <code>waitSeconds</code>, waits up to a minute and returns the output or the pending approval),</li><li><code>get_run</code> and <code>list_runs</code> for status,</li><li><code>resume_run</code> to answer an approval with its token and a decision.</li></ul><p>The endpoint uses the same bearer-token authentication as the REST API; give OpenClaw a principal with <code>agent:&lt;name&gt;:run</code>, which also lets it read the runs it starts. The owner answers approvals in the chamvi UI, signed in as a principal of their own. Add <code>agent:&lt;name&gt;:approve</code> only alongside <code>resumeTool: true</code>, accepting that the OpenClaw agent can then approve on its own (see the warning under <a href="#hooks-out">Hooks out</a>). This is how the owner says &quot;what&#39;s relevant in my mail today?&quot; in a chat and gets a run started.</p><h2 id="hooks-out" tabindex="-1">Hooks out <a class="header-anchor" href="#hooks-out" aria-label="Permalink to &quot;Hooks out&quot;">​</a></h2><p>Approval requests flow back through <a href="/reference/notify-openclaw"><code>@chamvi/notify-openclaw</code></a>: <code>POST &lt;openclaw&gt;&lt;hooks.path&gt;/agent</code> with OpenClaw&#39;s hooks token as bearer token, the notification&#39;s <code>idempotencyKey</code> as <code>Idempotency-Key</code> header and the delivery target (channel and recipient):</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> notifier = openclaw({</span></span>
<span class="line"><span style="color:#958A8B;">    // the OpenClaw gateway, reachable from the app</span></span>
<span class="line"><span style="color:#E6DFDE;">    baseUrl: </span><span style="color:#E7C58C;">&#39;http://openclaw:18789&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // OpenClaw&#39;s hooks.token, not the gateway token</span></span>
<span class="line"><span style="color:#E6DFDE;">    hooksToken: process.env.OPENCLAW_HOOKS_TOKEN </span><span style="color:#FF7B84;">??</span><span style="color:#E7C58C;"> &#39;&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // placeholders: the channel and recipient of your OpenClaw setup</span></span>
<span class="line"><span style="color:#E6DFDE;">    deliver: { channel: </span><span style="color:#E7C58C;">&#39;&lt;channel&gt;&#39;</span><span style="color:#E6DFDE;">, to: </span><span style="color:#E7C58C;">&#39;&lt;recipient&gt;&#39;</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#958A8B;">    // optional: a link to the approval in the UI, without the token</span></span>
<span class="line"><span style="color:#958A8B;">    // (only resumeTool: true puts the token and a resume_run call into the message)</span></span>
<span class="line"><span style="color:#E6DFDE;">    approvalUrl: ({ runId, approvalId }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E7C58C;"> \`https://chamvi.example/ui/approvals?run=</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">encodeURIComponent</span><span style="color:#E6DFDE;">(</span><span style="color:#E7C58C;">runId</span><span style="color:#E6DFDE;">)</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">&amp;approval=</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">encodeURIComponent</span><span style="color:#E6DFDE;">(</span><span style="color:#E7C58C;">approvalId</span><span style="color:#E6DFDE;">)</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store: </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> MemoryStore(),</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents,</span></span>
<span class="line"><span style="color:#958A8B;">    // agents name it with notify: &#39;openclaw&#39;</span></span>
<span class="line"><span style="color:#E6DFDE;">    notifiers: { openclaw: notifier },</span></span>
<span class="line"><span style="color:#E6DFDE;">    resumeSecret: process.env.RESUME_SECRET </span><span style="color:#FF7B84;">??</span><span style="color:#E7C58C;"> &#39;&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>In the OpenClaw configuration:</p><table tabindex="0"><thead><tr><th>Key</th><th>Value</th></tr></thead><tbody><tr><td><code>hooks.enabled</code></td><td><code>true</code> (hooks are off by default)</td></tr><tr><td><code>hooks.token</code></td><td>A dedicated token, passed as <code>hooksToken</code>; not the gateway token</td></tr><tr><td><code>hooks.path</code></td><td><code>/hooks</code> (the default <code>hooksPath</code>), or the same value on both sides</td></tr><tr><td><code>hooks.allowedAgentIds</code></td><td>Lists the <code>agentId</code> you pass, if any</td></tr><tr><td><code>mcp.servers</code></td><td>The app&#39;s <code>/mcp</code> endpoint with a token of a principal holding <code>agent:&lt;name&gt;:run</code>; add <code>agent:&lt;name&gt;:approve</code> only alongside <code>resumeTool: true</code> (see the warning below)</td></tr></tbody></table><p><code>deliver.channel</code> and <code>deliver.to</code> must name a concrete destination of your OpenClaw setup (OpenClaw refuses <code>channel: &#39;last&#39;</code> and a partial destination for hooks); the examples use placeholders.</p><p>For approvals the message includes how to answer: the <code>approvalUrl</code> link when configured, e.g. <code>https://&lt;app&gt;/ui/approvals?run=&lt;runId&gt;&amp;approval=&lt;approvalId&gt;</code>, which opens the run&#39;s approval in the UI, where the signed-in owner answers it through the token-less <code>POST /runs/:id/approve</code> (the owner&#39;s principal needs <code>agent:&lt;agent&gt;:approve</code> to answer and <code>run:read</code> or <code>agent:&lt;agent&gt;:run</code> for the UI to show the run&#39;s approval); else a line saying to answer in the chamvi UI or through <code>POST /runs/:id/approve</code>. By default the message carries no resume token (neither the link, the body nor a header). With <code>resumeTool: true</code> it also carries the token and a ready-made <code>resume_run</code> MCP call, so the owner can approve from the chat.</p><div class="warning custom-block"><p class="custom-block-title">With resumeTool the relay agent holds the token</p><p>The notification body is the tool input as the model wrote it and may repeat untrusted text (an issue body, a mail). OpenClaw wraps hook content as external, but that does not take tools away. By default the message carries no token, so a relay agent whose principal holds only <code>agent:&lt;name&gt;:run</code> cannot approve, whatever an injected instruction says. With <code>resumeTool: true</code> the relay agent holds the token, and with <code>agent:&lt;name&gt;:approve</code> (which <code>resume_run</code> needs) a turn that follows an injected instruction approves without the owner; the run then records the OpenClaw principal as approver. Turn <code>resumeTool</code> on only when you accept that.</p></div><h3 id="caveats" tabindex="-1">Caveats <a class="header-anchor" href="#caveats" aria-label="Permalink to &quot;Caveats&quot;">​</a></h3><ul><li>OpenClaw runs an agent turn on the message (it does not post raw text) and treats it as external content; the message asks that agent to keep every link and id verbatim (and the token, with <code>resumeTool</code>).</li><li>OpenClaw&#39;s idempotency replay is in memory and lasts 5 minutes after completion; a restart clears it. chamvi&#39;s <code>waiting.notifiedAt</code> and its per-approval lock are the primary dedupe, the key covers a response lost within those minutes.</li><li>A misconfigured hook (400, 401, 404) fails on every poll and reaches <code>onError</code> each time.</li><li>Keys over 256 characters (which OpenClaw ignores) or with characters outside visible ASCII are sent as <code>sha256:&lt;hex&gt;</code>.</li></ul><h2 id="in-the-cluster" tabindex="-1">In the cluster <a class="header-anchor" href="#in-the-cluster" aria-label="Permalink to &quot;In the cluster&quot;">​</a></h2><p>OpenClaw runs elsewhere in the cluster. It reaches each app at <code>http://&lt;service&gt;/mcp</code>, and the app reaches OpenClaw&#39;s hooks endpoint. Neither needs to be public.</p>`,18)])])}const y=a(s,[["render",l]]);export{u as __pageData,y as default};
